package com.plexus.personal.document.application;
import com.plexus.personal.document.domain.Document; import com.plexus.personal.document.infrastructure.*; import com.fasterxml.jackson.databind.JsonNode; import org.apache.tika.Tika; import org.springframework.stereotype.Service; import java.nio.file.*; import java.util.*;
@Service public class DocumentProcessingService { private final DocumentChunkMapper chunks; private final DocumentMapper documents; private final EmbeddingService embeddings; private final DocumentReviewClient reviewer; private final Tika tika=new Tika(); public DocumentProcessingService(DocumentChunkMapper c,DocumentMapper d,EmbeddingService e,DocumentReviewClient r){chunks=c;documents=d;embeddings=e;reviewer=r;} public void process(Document d,Path file){try{String raw=tika.parseToString(file.toFile()).trim(); if(raw.isBlank()) throw new IllegalArgumentException("文档没有可提取文本"); Quality q=quality(raw); String normalized=raw; String review=null; String status="READY"; String reason=null; if(q.needsReview){JsonNode result=reviewer.review(raw); if(result!=null&&result.path("normalized_text").isTextual()){normalized=result.path("normalized_text").asText().trim();review=result.toString();status="READY";}else{status="NEEDS_REVIEW";reason="文本包含疑似乱码，Agent 审核未完成";}} documents.updateQuality(d.id(),d.userId(),raw,normalized,q.status,q.score,review,status,reason); List<String> parts=split(normalized,1200,180); chunks.deleteByDocument(d.id()); for(int i=0;i<parts.size();i++){DocumentChunkRow r=new DocumentChunkRow();r.documentId=d.id();r.userId=d.userId();r.chunkIndex=i;r.content=parts.get(i);r.embedding=embeddings.embed(parts.get(i));chunks.insert(r);}}catch(Exception e){documents.updateStatus(d.id(),d.userId(),"FAILED",e.getMessage());throw new IllegalArgumentException("文档解析失败: "+e.getMessage(),e);}} private Quality quality(String s){long bad=s.chars().filter(c->c==0xfffd||c=='�').count();long controls=s.chars().filter(c->Character.isISOControl(c)&&c!='\n'&&c!='\r'&&c!='\t').count();double score=Math.max(0,1.0-(bad*4.0+controls*2.0)/Math.max(1,s.length()));return new Quality(score<.985||bad>0||controls>0?"SUSPECT":"PASS",score,score<.985||bad>0||controls>0);} private record Quality(String status,double score,boolean needsReview){} private List<String> split(String s,int size,int overlap){List<String> out=new ArrayList<>();int start=0;while(start<s.length()){int end=Math.min(s.length(),start+size);if(end<s.length()){int cut=s.lastIndexOf('\n',end);if(cut>start+size/2)end=cut;}String part=s.substring(start,end).trim();if(!part.isBlank())out.add(part);if(end>=s.length())break;start=Math.max(start+1,end-overlap);}return out;}}
